let spacing = 130; // size of the tile
let grid, cols, rows, theFont;
let letters = false;

let palettes = [
	["rgb(40,40,40)", "rgb(98,184,170)"],
	["rgb(0, 0, 4)", "rgb(228, 107, 15)"],
	["rgb(0, 0, 8)", "rgb(238, 43, 29)"],
	["rgb(225, 231, 219)", "rgb(238, 55, 52)"],
	["rgb(40, 51, 83)", "rgb(249, 193, 33)"],
	["rgb(12, 44, 5)", "rgb(101, 184, 40)"],
	["rgb(48, 49, 62)", "rgb(105, 198, 188)"],
	["rgb(49, 37, 41)", "rgb(136, 182, 187)"],
]
let palette;

function preload() {
	theFont = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/FamiljenGrotesk_Bold.ttf'); // from https://fonts.google.com/specimen/Familjen+Grotesk
}

function setup() {
	createCanvas(windowWidth * 0.99, windowHeight * 0.99); // anoying overflow scroll bars.....
	background(200);
	updateGrid();
	palette = random(palettes);
	if (random() < 0.5) palette = [palette[1], palette[0]]; // invert fg/bg colors in palette
	textFont(theFont);
}

function updateGrid() { // setup the orientation array
	cols = max(2, floor(width / spacing) - 1);
	rows = max(2, floor(height / spacing) - 1);
	grid = new Array(cols);
	for (let i = 0; i < cols; i++) {
		grid[i] = new Array(rows);
	}

	for (i = 0; i < cols * rows; i++) {
		let c = i % cols;
		let r = floor(i / cols);
		let rot = floor(random(4));
		let flip = floor(random(2));

		if ((rot == 0 && c == cols - 1) || (rot == 2 && c == 0) || (rot == 1 && r == rows - 1) || (rot == 3 && r == 0)) rot = (rot + 2) % 4;

		grid[c][r] = {
			rot: rot,
			flip: flip
		};
	}
}

function flip(mx, my) {
	let xoff = (width - (cols * spacing)) / 2;
	let yoff = (height - (rows * spacing)) / 2;

	let c = floor(map(mx, xoff, xoff + cols * spacing, 0, cols));
	let r = floor(map(my, yoff, yoff + rows * spacing, 0, rows));

	if (constrain(c, 0, cols - 1) != c || constrain(r, 0, rows - 1) != r) return;

	grid[c][r].flip = 1 - grid[c][r].flip;
}

function rot(mx, my, dir) {
	let xoff = (width - (cols * spacing)) / 2;
	let yoff = (height - (rows * spacing)) / 2;

	let c = floor(map(mx, xoff, xoff + cols * spacing, 0, cols));
	let r = floor(map(my, yoff, yoff + rows * spacing, 0, rows));

	if (constrain(c, 0, cols - 1) != c || constrain(r, 0, rows - 1) != r) return;

	grid[c][r].rot = (grid[c][r].rot + dir + 4) % 4;

	//twice to handle corners
	if ((grid[c][r].rot == 0 && c == cols - 1) || (grid[c][r].rot == 2 && c == 0) ||
		(grid[c][r].rot == 1 && r == rows - 1) || (grid[c][r].rot == 3 && r == 0)) grid[c][r].rot = (grid[c][r].rot + dir + 4) % 4;
	if ((grid[c][r].rot == 0 && c == cols - 1) || (grid[c][r].rot == 2 && c == 0) ||
		(grid[c][r].rot == 1 && r == rows - 1) || (grid[c][r].rot == 3 && r == 0)) grid[c][r].rot = (grid[c][r].rot + dir + 4) % 4;

}


function draw() {
	let xoff = (width - (cols * spacing)) / 2;
	let yoff = (height - (rows * spacing)) / 2;

	stroke(palette[0]);
	fill(palette[0]);
	strokeWeight(8);
	rect(xoff, yoff, cols * spacing, rows * spacing);

	strokeWeight(4);
	strokeJoin(ROUND);

	fill(palette[1]);

	for (i = 0; i < cols * rows; i++) {
		let c = i % cols;
		let r = floor(i / cols);
		let x = xoff + (c + 0.5) * spacing;
		let y = yoff + (r + 0.5) * spacing;

		theShape(x, y, spacing / 2, grid[c][r].flip, grid[c][r].rot * HALF_PI);

		if (letters) {
			push();
			noStroke();
			fill(palette[0]);
			textAlign(CENTER, CENTER);
			textSize(spacing / 2)
  		text(char(65+(c*r+grid[c][r].flip+grid[c][r].rot)%26), x, y-spacing*0.1);  //debug of orientation array
      pop();
		}
	}
}

function theShape(x, y, r, flip, rot) {
	// For the bezier approximation of quarter arcs
	let a = 1.00005519;
	let b = 0.55342686;
	let c = 0.99873585;

	rot = rot || 0;
	push();
	translate(x, y);
	let a1 = a * r;
	let b1 = b * r;
	let c1 = c * r;
	rotate(rot);
	if (flip) scale(1, -1);
	beginShape();
	vertex(0, a1);
	bezierVertex(-b1, c1, -c1, b1, -a1, 0);
	bezierVertex(-c1, -b1, -b1, -c1, 0, -a1);
	bezierVertex(b1, -c1, c1, -b1, a1, 0);
	bezierVertex(2 * r - c1, b1, 2 * r - b1, c1, 2 * r, a1);
	endShape(CLOSE);
	pop();
}

// Resize the canvas when the
// browser's size changes.
function windowResized() {
	resizeCanvas(windowWidth * 0.99, windowHeight * 0.99);
	updateGrid();
}

//disable default right mouse click
document.addEventListener("contextmenu", (event) => event.preventDefault(), "true")

//left click restarts, right click does an image capture
let lapse = 0; // mouse timer
function mousePressed() {
	if (millis() - lapse > 400) {
		lapse = millis();
		if (mouseButton === RIGHT) {
			save("img_" + nf(year(), 4) + nf(month(), 2) + nf(day(), 2) + nf(hour(), 2) + nf(minute()) + nf(second()) + ".png");
		} else if (mouseButton === CENTER) {
			flip((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
		} else {
			setup(); // start a new image
		}
	}
	return (true)
}

function mouseWheel(event) {
	rot((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), event.delta / abs(event.delta));
	return false;
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
        BoxGeometry: class {}
    };
}
if (typeof window.Tone === 'undefined') {
    window.Tone = {
        Player: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Players: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Sampler: class { triggerAttackRelease() {} connect() {} toDestination() {} },
        Sequence: class { start() {} stop() {} },
        Transport: { start: function() {}, stop: function() {}, bpm: { value: 120 } }
    };
}
if (typeof window.createREGL === 'undefined') {
    window.createREGL = function() {
        const regl = function() {};
        regl.texture = function() { return { resize: function() {} }; };
        regl.buffer = function() { return { subdata: function() {} }; };
        regl.framebuffer = function() { return { use: function(cb) { cb(); } }; };
        return regl;
    };
}
if (typeof window.Voronoi === 'undefined') {
    window.Voronoi = class {
        compute() { return { cells: [], edges: [] }; }
    };
}
if (typeof window.qrcode === 'undefined') {
    window.qrcode = function(data) {
        return {
            createImgTag: function() { return ""; },
            createTableTag: function() { return ""; },
            createSvgTag: function() { return ""; }
        };
    };
    window.qrcode.stringToBytes = function(s) { return []; };
}
if (typeof window.PolyK === 'undefined') {
    window.PolyK = {
        Slice: function() { return []; },
